#[test]
fn a_deep_document_streams_as_jq_streams_it_7567() -> Result<()> {
    let mut failures = Vec::new();
    for &(flags, program, input, stdout, stderr, status) in ROWS {
        let mut args = flags.to_vec();
        args.push(program);
        let (output, code) = spawn_jq(&args, Some(input.as_bytes()))?;
        let got = (
            String::from_utf8_lossy(&output.stdout).into_owned(),
            String::from_utf8_lossy(&output.stderr).into_owned(),
            code,
        );
        if got != (stdout.to_string(), stderr.to_string(), status) {
            failures.push(format!("{flags:?} {program:?} over {input:?}: got {got:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} rows differ:\n{}",
        failures.len(),
        ROWS.len(),
        failures.join("\n")
    );
    Ok(())
}
